create table admins (id bigint not null, totp_secret varchar(100) not null, primary key (id));
create table applications (applied_at timestamp(6) not null, id bigint generated by default as identity, job_id bigint not null, job_seeker_id bigint not null, application_status varchar(15) not null check (application_status in ('UNDER_REVIEW','ACCEPTED','DECLINED')), cover_letter varchar(500), hr_notes varchar(500), primary key (id), unique (job_seeker_id, job_id));
create table companies (agree_to_terms boolean, id bigint not null, industry_type varchar(15) check (industry_type in ('TECHNOLOGY','HEALTHCARE','EDUCATION','FINANCE','ECOMMERCE','MEDIA','OTHERS')), company_name varchar(50), logo_image_path varchar(100), address varchar(150), company_description varchar(500), instagram_url varchar(255), linkedin_url varchar(255), twitter_url varchar(255), website_url varchar(255), youtube_url varchar(255), primary key (id));
create table human_resources (company_id bigint not null, id bigint not null, contact varchar(15), full_name varchar(50), pp_image_path varchar(100), primary key (id));
create table job_compatible_disabilities (job_id bigint not null, disability_type varchar(10) not null check (disability_type in ('VISUAL','HEARING','MOBILITY','COGNITIVE')));
create table job_seeker_certifications (job_seeker_id bigint not null, certification_file_path varchar(100) not null);
create table job_seeker_skills (job_seeker_id bigint not null, skill varchar(50) not null);
create table job_seekers (id bigint not null, academic_year varchar(10), disability_type varchar(10) check (disability_type in ('VISUAL','HEARING','MOBILITY','COGNITIVE')), education_level varchar(20) check (education_level in ('HIGH_SCHOOL','COLLEGE_STUDENT','BACHELOR','MASTER','DOCTORATE')), full_name varchar(50), cv_document_path varchar(100), pp_image_path varchar(100), address varchar(150), about_me varchar(500), job_type_preference varchar(255) check (job_type_preference in ('FULL_TIME','FREELANCE','CONTRACT','REMOTE','INTERNSHIP')), primary key (id));
create table jobs (min_years_experience integer, salary numeric(12,2), company_id bigint not null, created_at timestamp(6) not null, id bigint generated by default as identity, registration_deadline timestamp(6), updated_at timestamp(6) not null, job_type varchar(10) not null check (job_type in ('FULL_TIME','FREELANCE','CONTRACT','REMOTE','INTERNSHIP')), publication_status varchar(10) not null check (publication_status in ('OPEN','CLOSED')), minimum_education varchar(20) check (minimum_education in ('HIGH_SCHOOL','COLLEGE_STUDENT','BACHELOR','MASTER','DOCTORATE')), title varchar(50) not null, job_description varchar(1000), primary key (id));
create table logs (created_at timestamp(6) not null, id bigint generated by default as identity, actor_role varchar(15) not null, action varchar(50) not null, actor_username varchar(50) not null, primary key (id));
create table users (is_profile_completed boolean not null, created_at timestamp(6) not null, id bigint generated by default as identity, updated_at timestamp(6) not null, role varchar(15) not null check (role in ('ADMIN','COMPANY','JOB_SEEKER','HUMAN_RESOURCE')), username varchar(50) not null unique, password varchar(100) not null, primary key (id));
alter table if exists admins add constraint FKanhsicqm3lc8ya77tr7r0je18 foreign key (id) references users;
alter table if exists applications add constraint FK65weib1lru9dkrbto5pv389vi foreign key (job_id) references jobs;
alter table if exists applications add constraint FKnh8v752vltdrjp2stjph77gha foreign key (job_seeker_id) references job_seekers;
